insert into kafaa_technologies (id, name_en, name_ar, description_en, description_ar, category, skill_ids, status, version, created_by, created_at, updated_by, updated_at, sort) values
('tech-process-historian', 'Plant process historian and trend data', 'مؤرخ بيانات العمليات واتجاهات المحطة', 'Time-series records of plant parameters used to trend equipment and system performance and to check data quality.', 'سجلات زمنية لمعاملات المحطة تُستخدم لتتبّع اتجاهات أداء المعدات والأنظمة والتحقق من جودة البيانات.', 'plant_data', array['sk-fs-ai-plantdata','sk-en-02-perf','sk-en-02']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 1),
('tech-condition-monitoring', 'Condition-monitoring analytics', 'تحليلات مراقبة الحالة', 'Vibration, thermal and performance analytics that flag equipment drifting from normal so engineers can triage early.', 'تحليلات الاهتزاز والحرارة والأداء التي تنبّه إلى المعدات التي تنحرف عن وضعها الطبيعي ليتمكن المهندسون من الفرز مبكراً.', 'analytics', array['sk-fs-ai-anomaly','sk-en-02-perf']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 2),
('tech-dashboards', 'Data visualisation dashboards', 'لوحات عرض البيانات المرئية', 'Dashboards that turn exported plant, outage and training data into charts people can act on, with the data source shown.', 'لوحات تحوّل بيانات المحطة والانقطاعات والتدريب المصدّرة إلى رسوم بيانية يمكن العمل بها، مع إظهار مصدر البيانات.', 'analytics', array['sk-da-01-analysis','sk-da-01']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 3),
('tech-scripting', 'General-purpose scripting for engineering analysis', 'البرمجة النصية العامة للتحليل الهندسي', 'Short scripts that repeat an engineering calculation or clean a data export the same way every time, reviewed like any calculation.', 'نصوص برمجية قصيرة تكرر حساباً هندسياً أو تنظّف بيانات مصدّرة بالطريقة نفسها كل مرة، وتُراجع مثل أي حساب.', 'automation', array['sk-da-01-scripting']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 4),
('tech-workflow-automation', 'Low-code workflow automation', 'أتمتة سير العمل منخفضة البرمجة', 'Configured workflows that route forms, approvals and reminders without custom code, inside the approved digital estate.', 'مسارات عمل مهيأة توجّه النماذج والموافقات والتذكيرات دون برمجة مخصصة، ضمن البيئة الرقمية المعتمدة.', 'automation', array['sk-fs-ai-automation']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 5),
('tech-data-pipelines', 'Data pipelines and data-quality checks', 'خطوط البيانات وفحوص جودتها', 'Repeatable extracts, transformations and quality checks that move records between systems without manual retyping.', 'عمليات استخراج وتحويل وفحص جودة قابلة للتكرار تنقل السجلات بين الأنظمة دون إعادة إدخال يدوية.', 'plant_data', array['sk-fs-ai-dataeng','sk-fs-ai-data-care']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 6),
('tech-twin-platform', 'Digital-twin modelling platform', 'منصة نمذجة التوائم الرقمية', 'Physics and data models of plant systems that are validated against measured behaviour before anyone relies on them.', 'نماذج فيزيائية وبيانية لأنظمة المحطة يُتحقق منها مقابل السلوك المقاس قبل الاعتماد عليها.', 'digital_twin', array['sk-da-01-twins','sk-fs-ai-twin']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 7),
('tech-remote-monitoring', 'Remote monitoring of automated control', 'المراقبة عن بُعد للتحكم المؤتمت', 'Displays and alarms that let people oversee automated or remotely operated functions and know when to take control.', 'شاشات وإنذارات تتيح الإشراف على الوظائف المؤتمتة أو المشغّلة عن بُعد ومعرفة متى يجب التدخل.', 'digital_twin', array['sk-da-01-remote']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 8),
('tech-ar-inspection', 'Augmented-reality inspection and guidance', 'الفحص والإرشاد بالواقع المعزز', 'Head-worn or tablet overlays that show step guidance, labels and checkpoints in the field and in training rooms.', 'طبقات عرض على الرأس أو الجهاز اللوحي تُظهر إرشاد الخطوات والملصقات ونقاط التحقق في الموقع وفي قاعات التدريب.', 'inspection', array['sk-fs-ai-xr']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 9),
('tech-remote-inspection', 'Robotic and remote inspection', 'الفحص الآلي والفحص عن بُعد', 'Crawlers, drones and remote cameras that inspect areas that are hard or high-dose to reach, with the data logged.', 'زواحف وطائرات مسيّرة وكاميرات عن بُعد تفحص المناطق الصعبة أو عالية الجرعة، مع تسجيل البيانات.', 'inspection', array['sk-fs-dp-robotics','sk-mp-01-remote']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 10),
('tech-erounds', 'Mobile electronic operator rounds', 'جولات المشغّل الإلكترونية على الأجهزة المحمولة', 'Handheld rounds that capture readings against limits in the field and replace paper log sheets.', 'جولات بالأجهزة المحمولة تسجّل القراءات مقابل الحدود في الموقع وتحل محل سجلات الورق.', 'work_management', array['sk-fs-dp-rounds','sk-co-01-rounds']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 11),
('tech-ework', 'Electronic work packages and maintenance management', 'حزم العمل الإلكترونية وإدارة الصيانة', 'Work orders, packages and sign-offs held electronically from planning to close-out, with the history kept.', 'أوامر العمل والحزم والاعتمادات محفوظة إلكترونياً من التخطيط حتى الإغلاق، مع الاحتفاظ بالسجل.', 'work_management', array['sk-fs-dp-ework','sk-mp-01']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 12),
('tech-scheduling', 'Critical-path outage scheduling', 'جدولة الانقطاعات بالمسار الحرج', 'Schedules that link outage activities, resources and windows so slippage on the critical path shows early.', 'جداول تربط أنشطة الانقطاع والموارد والنوافذ الزمنية لتظهر التأخيرات على المسار الحرج مبكراً.', 'work_management', array['sk-mp-01-outage']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 13),
('tech-genai-assistant', 'Governed generative-AI assistants', 'مساعدات الذكاء الاصطناعي التوليدي الخاضعة للحوكمة', 'Approved assistants for drafting, search and summaries, used under the AI register rules and always checked by a person.', 'مساعدات معتمدة للصياغة والبحث والتلخيص، تُستخدم وفق قواعد سجل الذكاء الاصطناعي ويراجعها شخص دائماً.', 'ai_tools', array['sk-fs-ai-use','sk-fs-ai-verify','sk-fs-ai-prompt','sk-da-02','sk-da-02-review']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 14),
('tech-digital-ic-diagnostics', 'Digital I&C platform diagnostics', 'تشخيص منصة القياس والتحكم الرقمية', 'Self-diagnostics and maintenance displays of the digital instrumentation and control platform, read by trained technicians.', 'التشخيص الذاتي وشاشات الصيانة لمنصة القياس والتحكم الرقمية، ويقرؤها فنيون مدرّبون.', 'plant_data', array['sk-mp-02-dic','sk-fs-dp-dic']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 15),
('tech-lab-information', 'Laboratory information management', 'إدارة معلومات المختبر', 'Sample tracking, results and instrument records for the chemistry laboratories, with review and approval kept.', 'تتبّع العينات والنتائج وسجلات الأجهزة لمختبرات الكيمياء، مع الاحتفاظ بالمراجعة والاعتماد.', 'analytics', array['sk-ch-02-labqa']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 16),
('tech-dose-tracking', 'Electronic dosimetry and dose tracking', 'قياس الجرعات الإلكتروني وتتبّعها', 'Electronic dosimeters and dose records that follow exposure against work permits and planning estimates.', 'مقاييس جرعات إلكترونية وسجلات جرعات تتابع التعرض مقابل تصاريح العمل وتقديرات التخطيط.', 'plant_data', array['sk-rp-01-dose']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 17),
('tech-eprocurement', 'Electronic procurement and supplier portals', 'المشتريات الإلكترونية وبوابات الموردين', 'Requisitions, bids and supplier documents handled electronically, with technical and quality reviews recorded.', 'طلبات الشراء والعطاءات ووثائق الموردين تُدار إلكترونياً، مع تسجيل المراجعات الفنية ومراجعات الجودة.', 'work_management', array['sk-fs-dp-procurement']::text[], 'active', 1, 'p-training-mgr', '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', 18)
insert into kafaa_skill_signal_runs (id, quarter, method, status, counts, published_by, published_role, published_at, summary_en, summary_ar) values
('ssr:2025-Q4', '2025-Q4', 'fs70-v1', 'published', '{"now":0,"growing":2,"considered":24,"suppressed":21,"shown":3}'::jsonb, 'p-k-hr-analyst', 'hr_analyst', '2026-01-12T08:00:00Z', '2 growing (led by Pre-job briefs graded to risk, Pre-job briefs and post-job reviews).', '2 في نمو (في مقدمتها إحاطات ما قبل العمل المتدرجة حسب المخاطر، إحاطات ما قبل العمل ومراجعات ما بعده).'),
('ssr:2026-Q1', '2026-Q1', 'fs70-v1', 'published', '{"now":0,"growing":0,"considered":48,"suppressed":50,"shown":3}'::jsonb, 'p-k-hr-analyst', 'hr_analyst', '2026-04-09T08:00:00Z', 'No skill crossed the published thresholds this quarter: every signal was under 10 or did not rise enough.', 'لم تتجاوز أي مهارة العتبات المنشورة هذا الربع: كانت كل إشارة أقل من 10 أو لم ترتفع بما يكفي.'),
('ssr:2026-Q2', '2026-Q2', 'fs70-v1', 'published', '{"now":0,"growing":10,"considered":79,"suppressed":74,"shown":10}'::jsonb, 'p-chco', 'hr_director', '2026-07-08T08:00:00Z', '10 growing (led by Questioning attitude and raising concerns, APR-1400 integrated plant systems, AI output verification and challenge).', '10 في نمو (في مقدمتها موقف التساؤل ورفع المخاوف، أنظمة محطة APR-1400 المتكاملة، التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها).'),
('ssr:2026-Q3', '2026-Q3', 'fs70-v1', 'published', '{"now":7,"growing":12,"considered":79,"suppressed":81,"shown":26}'::jsonb, 'p-k-hr-analyst', 'hr_analyst', '2026-10-06T08:00:00Z', '7 in demand now (led by AI output verification and challenge, Digital tools and data literacy, Data analysis and visualisation); 12 growing (led by Prompt and agent literacy, Plant-data quality, Everyday use of approved AI tools).', '7 مطلوبة الآن (في مقدمتها التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها، الأدوات الرقمية ومحو الأمية في البيانات، تحليل البيانات وتصويرها)؛ 12 في نمو (في مقدمتها الإلمام بصياغة الأوامر والوكلاء الذكيين، جودة بيانات المحطة، الاستخدام اليومي لأدوات الذكاء الاصطناعي المعتمدة).')
insert into kafaa_wallet_targets (id, metric, pct, due_on, note_en, note_ar, set_by, set_by_role, set_at, status, version, history, benchmark_ids, sources) values
('wt-core-five', 'core_five_complete', 60, '2027-12-31', 'Demo parameter set by leadership: share of staff holding the complete core-five Future Skills Wallet by the end of 2027. A leadership decision shown beside the measured counter, not a claim.', 'معامل للعرض التوضيحي حددته القيادة: نسبة الموظفين الذين يحملون محفظة مهارات المستقبل الكاملة بمهاراتها الخمس الأساسية بنهاية 2027. قرار قيادي يُعرض بجانب العدّاد المقيس، وليس ادعاءً.', 'p-chco', 'hr_director', '2026-10-05T09:00:00Z', 'active', 1, '[]'::jsonb, array['JAHIZ','UAE-AI','UAE-PEERS']::text[], '[{"label":"WAM · Jahiz, UAE''s digital platform for upskilling all federal government talents with future skills","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"label":"Khaleej Times · Abu Dhabi to train government employees in AI by 2027","url":"https://www.khaleejtimes.com/abu-dhabi-train-23000-government-employees-ai-by-2027","as_of":"2026-10-10"}]'::jsonb)
