('ib-2026-all-v2', 2026, 'all', 2, 'published', '[{"module_id":"ind-ai-basics","status":"partial","basis":"national_curriculum","source_url":"https://www.middleeastainews.com/p/uae-rolls-out-ai-school-curriculum","note_en":"UAE schools teach AI from the 2025-26 academic year: 2026 school leavers had one year of it.","note_ar":"تُدرّس مدارس الإمارات الذكاء الاصطناعي منذ العام الدراسي 2025-2026: درسه خريجو المدارس لعام 2026 لمدة عام واحد."},{"module_id":"ind-ai-responsible","status":"not_held","basis":"none","source_url":null,"note_en":"","note_ar":""},{"module_id":"ind-digital","status":"held","basis":"intake_diagnostic","source_url":null,"note_en":"Intake diagnostic of the 2025 intake (synthetic summary).","note_ar":"التشخيص عند الالتحاق لدفعة 2025 (ملخص تجريبي)."},{"module_id":"ind-data","status":"partial","basis":"intake_diagnostic","source_url":null,"note_en":"Intake diagnostic of the 2025 intake (synthetic summary).","note_ar":"التشخيص عند الالتحاق لدفعة 2025 (ملخص تجريبي)."},{"module_id":"ind-energy","status":"not_held","basis":"none","source_url":null,"note_en":"","note_ar":""},{"module_id":"ind-smr","status":"not_held","basis":"none","source_url":null,"note_en":"","note_ar":""}]'::jsonb, 'AI basics shortened to a refresher once the school AI curriculum reached the 2026 school leavers.', 'اختُصرت أساسيات الذكاء الاصطناعي إلى جلسة تذكيرية بعد أن وصل منهج الذكاء الاصطناعي المدرسي إلى خريجي 2026.', 'p-k-hr-analyst', '2026-05-10T09:00:00Z', 'p-chco', '2026-05-12T09:00:00Z', true, true),
('ib-2026-gdp-v1', 2026, 'gdp', 1, 'published', '[{"module_id":"ind-ai-basics","status":"partial","basis":"programme_curriculum","source_url":null,"note_en":"Most graduates took an AI or data course at university (intake diagnostic, synthetic).","note_ar":"درس معظم الخريجين مقرراً في الذكاء الاصطناعي أو البيانات في الجامعة (تشخيص تجريبي)."},{"module_id":"ind-digital","status":"held","basis":"programme_curriculum","source_url":null,"note_en":"Degree coursework (synthetic summary).","note_ar":"مقررات الدرجة الجامعية (ملخص تجريبي)."},{"module_id":"ind-data","status":"held","basis":"programme_curriculum","source_url":null,"note_en":"Degree coursework (synthetic summary).","note_ar":"مقررات الدرجة الجامعية (ملخص تجريبي)."}]'::jsonb, 'Graduate Development Program intake: degree coursework covers the digital modules.', 'دفعة برنامج تطوير الخريجين: تغطي مقررات الدرجة الجامعية الوحدات الرقمية.', 'p-k-hr-analyst', '2026-05-10T10:00:00Z', 'p-chco', '2026-05-12T10:00:00Z', true, true),
('ib-2027-all-v1', 2027, 'all', 1, 'draft', '[{"module_id":"ind-ai-basics","status":"held","basis":"national_curriculum","source_url":"https://www.middleeastainews.com/p/uae-rolls-out-ai-school-curriculum","note_en":"Two school years of the UAE AI curriculum (from 2025-26); to be confirmed by the 2027 intake diagnostic.","note_ar":"عامان دراسيان من منهج الذكاء الاصطناعي في الإمارات (منذ 2025-2026)؛ يُؤكَّد بتشخيص دفعة 2027."},{"module_id":"ind-ai-responsible","status":"partial","basis":"national_curriculum","source_url":"https://www.middleeastainews.com/p/uae-rolls-out-ai-school-curriculum","note_en":"The school curriculum covers ethics and responsible use.","note_ar":"يغطي المنهج المدرسي الأخلاقيات والاستخدام المسؤول."},{"module_id":"ind-digital","status":"held","basis":"intake_diagnostic","source_url":null,"note_en":"Intake diagnostic of the 2026 intake (synthetic summary).","note_ar":"التشخيص عند الالتحاق لدفعة 2026 (ملخص تجريبي)."},{"module_id":"ind-data","status":"partial","basis":"intake_diagnostic","source_url":null,"note_en":"Intake diagnostic of the 2026 intake (synthetic summary).","note_ar":"التشخيص عند الالتحاق لدفعة 2026 (ملخص تجريبي)."}]'::jsonb, 'Draft for the 2027 intake, waiting for HR to publish.', 'مسودة لدفعة 2027 بانتظار نشرها من الموارد البشرية.', 'p-k-hr-analyst', '2026-10-05T09:00:00Z', null, null, false, true)
insert into kafaa_induction_modules (id, sort, area, title_en, title_ar, summary_en, summary_ar, hours, refresh_hours, mandatory, skill_ids, listed) values
('ind-ai-basics', 1, 'ai', 'AI basics: what AI is and is not', 'أساسيات الذكاء الاصطناعي: ما هو وما ليس هو', 'Patterns, predictions and limits of AI tools, with plant examples.', 'الأنماط والتنبؤات وحدود أدوات الذكاء الاصطناعي، مع أمثلة من المحطة.', 3, 1, false, array['sk-fs-ai-use']::text[], true),
('ind-ai-responsible', 2, 'ai', 'Responsible AI: checking outputs, bias and privacy', 'الذكاء الاصطناعي المسؤول: التحقق من النواتج والتحيز والخصوصية', 'Verify before use, protect personal data, recognise bias.', 'تحقق قبل الاستخدام، واحمِ البيانات الشخصية، وتعرّف على التحيز.', 2, 1, false, array['sk-fs-ai-verify','sk-fs-ai-data-care']::text[], true),
('ind-ai-enec', 3, 'ai', 'AI at ENEC: approved tools and the human check', 'الذكاء الاصطناعي في ENEC: الأدوات المعتمدة والمراجعة البشرية', 'Which tools are approved for which tasks, and the rule that a qualified person checks every AI output. Always taught: it is ENEC-specific.', 'أي الأدوات معتمدة لأي المهام، وقاعدة أن يراجع شخص مؤهل كل ناتج للذكاء الاصطناعي. يُدرَّس دائماً لأنه خاص بـ ENEC.', 1.5, 0, true, array['sk-fs-ai-use','sk-fs-ai-verify']::text[], true),
('ind-digital', 4, 'digital', 'Digital essentials: files, collaboration and records', 'الأساسيات الرقمية: الملفات والتعاون والسجلات', 'Working with shared files, collaboration tools and controlled records.', 'العمل بالملفات المشتركة وأدوات التعاون والسجلات المضبوطة.', 3, 1, false, array['sk-fs-tr-techlit']::text[], true),
('ind-data', 5, 'digital', 'Reading data: trends, charts and dashboards', 'قراءة البيانات: الاتجاهات والرسوم البيانية ولوحات المعلومات', 'Reading a trend, spotting an outlier and asking where the data came from.', 'قراءة الاتجاه، ورصد القيمة الشاذة، والسؤال عن مصدر البيانات.', 2, 1, false, array['sk-fs-ai-plantdata']::text[], true),
('ind-cyber', 6, 'cyber', 'Cyber hygiene awareness', 'التوعية بالنظافة السيبرانية', 'Phishing, passwords, removable media and how to report. All-staff awareness; always taught.', 'التصيد الاحتيالي وكلمات المرور ووسائط التخزين القابلة للإزالة وطريقة الإبلاغ. توعية لجميع الموظفين؛ تُدرَّس دائماً.', 1.5, 0, true, array['sk-fs-cy-phishing','sk-fs-cy-media','sk-fs-cy-report']::text[], true),
('ind-energy', 7, 'energy', 'Energy and nuclear basics: from fission to the grid', 'أساسيات الطاقة والطاقة النووية: من الانشطار إلى الشبكة', 'How fission makes heat, heat makes steam and steam makes electricity.', 'كيف ينتج الانشطار الحرارة، وتنتج الحرارة البخار، وينتج البخار الكهرباء.', 4, 1.5, false, '{}'::text[], true),
('ind-smr', 8, 'smr', 'Next-generation reactors orientation', 'التعريف بمفاعلات الجيل القادم', 'What small modular and advanced reactors would change and keep. Planning view: no deployment decision implied.', 'ما الذي ستغيره المفاعلات النمطية الصغيرة والمتقدمة وما الذي ستبقيه. رؤية تخطيطية: لا يعني أي قرار بالنشر.', 1.5, 0.5, false, array['sk-fs-adv-smr']::text[], true),
('ind-safety-culture', 9, 'safety', 'Nuclear safety culture and human performance tools', 'ثقافة السلامة النووية وأدوات الأداء البشري', 'Questioning attitude, conservative decisions and the human performance tools. Mandatory for every joiner.', 'الموقف التساؤلي والقرارات المتحفظة وأدوات الأداء البشري. إلزامي لكل منضم جديد.', 6, 0, true, '{}'::text[], true),
('ind-radiation', 10, 'radiation', 'Radiation protection basics', 'أساسيات الوقاية من الإشعاع', 'Dose, time, distance and shielding, and the rules in controlled areas. Mandatory.', 'الجرعة والزمن والمسافة والتدريع، والقواعد في المناطق المراقبة. إلزامي.', 4, 0, true, '{}'::text[], true),
('ind-site', 11, 'site', 'Site induction', 'التعريف بالموقع', 'The site induction every joiner completes before plant work. Mandatory.', 'التعريف بالموقع الذي يكمله كل منضم قبل العمل في المحطة. إلزامي.', 3, 0, true, '{}'::text[], true),
('ind-company', 12, 'company', 'ENEC, Barakah and the UAE peaceful nuclear programme', 'ENEC وبراكة والبرنامج النووي السلمي الإماراتي', 'Who we are, how the organisation works and where to get help. Always taught.', 'من نحن، وكيف تعمل المؤسسة، وأين تجد المساعدة. يُدرَّس دائماً.', 2, 0, true, '{}'::text[], true)
