('as-future-2', 'w-lo-02', 'staff', '2026-10-10T08:15:00Z', '2026-11-09', 'none', false, 2, null, '/my/ai-fluency', 'none', null, '2026-10-10T08:15:00Z', 'career'),
('as-future-3', 'w-ro-05', 'staff', '2026-10-10T10:05:00Z', '2026-11-09', 'none', false, 4, null, '/skills/sk-fs-ai-twin', 'none', null, '2026-10-10T10:05:00Z', 'career'),
('as-future-4', null, 'public', '2026-10-10T12:30:00Z', '2026-11-09', 'none', false, 2, 'anon-seed-fs76', '/careers/roles/senior-reactor-operator', 'none', null, '2026-10-10T12:30:00Z', null)
insert into kafaa_advisor_turns (id, session_id, person_id, speaker, text, citations, refused, refusal_category, ts, intent, confidence, redacted, mode, submode) values
('as-future-1-1', 'as-future-1', 'w-ro-03', 'user', 'How will my role change by 2030?', '[]'::jsonb, false, null, '2026-10-10T06:40:00Z', 'future.role_2030.personal', null, false, 'staff', 'career'),
('as-future-1-2', 'as-future-1', 'w-ro-03', 'dalil', 'Reactor Operator (RO) in 2030 (Mastery Builder) is driven by AI assistance, Digital I&C, Digital twin, SMR and advanced-reactor design. The 2030 profile adds or raises 2 requirements. At your current levels you meet 90% of it: about 4 months of development at two months per level. Planning assumption, no deployment decision implied.', '[{"label":"My role in 2030","url":"/my/role-2030"},{"label":"Reactor Operator (RO) · role transformation map","url":"/careers/roles/reactor-operator/transformation"},{"label":"Reactor Operator (RO)","url":"/careers/roles/reactor-operator"}]'::jsonb, false, null, '2026-10-10T06:40:00Z', 'future.role_2030.personal', 1, false, 'staff', 'career'),
('as-future-1-3', 'as-future-1', 'w-ro-03', 'user', 'Which pathway closes my gap?', '[]'::jsonb, false, null, '2026-10-10T06:40:00Z', 'future.pathway_gap.personal', null, false, 'staff', 'career'),
('as-future-1-4', 'as-future-1', 'w-ro-03', 'dalil', 'These 3 pathways close your 2030 gaps first, ranked the same way as your Learning Coach. Indicative only: a planning view, never a decision about you.
insert into kafaa_dalil_intents (id, kind, audience, feature, title_en, title_ar, summary_en, summary_ar, examples_en, examples_ar, cites, sources, benchmark_ids, enabled, changed_role, changed_at, change_note, sort) values
('future.role_2030', 'role_2030', 'both', 'FS11', 'How my role changes by 2030', 'كيف يتغير دوري بحلول 2030', 'The role transformation map: the technology drivers, which tasks grow with people, become AI-assisted or shrink, what the 2030 profile adds and, for you, your time-to-ready. A planning assumption, no deployment decision implied.', 'خريطة تحول الدور: محركات التقنية، والمهام التي تنمو مع الناس أو تصبح مدعومة بالذكاء الاصطناعي أو تتقلص، وما يضيفه ملف 2030، ووقتك المقدّر للجاهزية. افتراض تخطيطي ولا يعني أي قرار نشر.', array['How will my role change by 2030?','How will the senior reactor operator role change by 2030?']::text[], array['كيف سيتغير دوري بحلول 2030؟','كيف سيتغير دور مشغل المفاعل الأول بحلول 2030؟']::text[], array['/my/role-2030','/careers/roles/:slug/transformation','/careers/roles/:slug']::text[], '[{"label":"Workforce Singapore · Jobs Transformation Maps","url":"https://wsg.gov.sg/for-employers/jobs-transformation-maps.html","as_of":"2026-10-10"},{"label":"SkillsFuture Singapore · Careers and Skills Passport","url":"https://www.myskillsfuture.gov.sg/csp","as_of":"2026-10-10"}]'::jsonb, array['SG-CAREER']::text[], true, null, null, null, 1),
('future.ai_rung', 'ai_rung', 'both', 'FS09', 'Which AI rung I need', 'درجة الذكاء الاصطناعي التي أحتاجها', 'The AI fluency ladder target for a job family, and for you the rung your evidence shows and the cells still missing, each with the learning that evidences it. Self-ratings never move the rung.', 'هدف سلم الطلاقة في الذكاء الاصطناعي لكل عائلة وظيفية، ولك الدرجة التي تُظهرها أدلتك والخلايا الناقصة مع التعلم الذي يثبتها. التقييم الذاتي لا يرفع الدرجة أبداً.', array['Which AI rung do I need?','What AI fluency does a reactor operator need?']::text[], array['ما درجة الذكاء الاصطناعي التي أحتاجها؟','ما مستوى الطلاقة في الذكاء الاصطناعي الذي يحتاجه مشغل المفاعل؟']::text[], array['/learn/ai-fluency','/my/ai-fluency']::text[], '[{"label":"European Commission · Living repository of AI-literacy practices (EU AI Act Article 4)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-10"}]'::jsonb, array['AI-LIT']::text[], true, null, null, null, 2),
('future.skill_crosswalk', 'skill_crosswalk', 'public', 'FS08', 'What a skill means and its crosswalk', 'معنى المهارة ومقابلها في الأطر الدولية', 'The skill page in plain words and its published crosswalk to ESCO, O*NET, SFIA, DigComp and the other frameworks, with the match type, the review state and the source. Label-level rows say "code pending review".', 'صفحة المهارة بلغة واضحة ومقابلها المنشور في ESCO وO*NET وSFIA وDigComp وغيرها، مع نوع المطابقة وحالة المراجعة والمصدر. الصفوف على مستوى التسمية تقول "الرمز قيد المراجعة".', array['What is the ESCO equivalent of digital twin validation?','What does AI output verification and challenge mean?']::text[], array['ما المقابل في ESCO لمهارة التحقق من التوأم الرقمي؟','ما معنى مهارة التحقق من مخرجات الذكاء الاصطناعي ومساءلتها؟']::text[], array['/skills/:id','/skills/frameworks']::text[], '[{"label":"ESCO v1.2.1 skills pillar (European Commission)","url":"https://esco.ec.europa.eu/en/classification/skill_main","as_of":"2026-10-10"},{"label":"SkillsFuture Singapore · Careers and Skills Passport","url":"https://www.myskillsfuture.gov.sg/csp","as_of":"2026-10-10"}]'::jsonb, array['SG-CAREER']::text[], true, null, null, null, 3),
('future.pathway_gap', 'pathway_gap', 'personal', 'FS17', 'Which pathway closes my gap', 'أي مسار تعلم يسد فجوتي', 'The future-skill learning pathways that close your 2030 gaps first, ranked the same way as the Learning Coach, each with why it was picked. Anonymous visitors are pointed to the public skills catalogue.', 'مسارات تعلم مهارات المستقبل التي تسد فجوات 2030 لديك أولاً، مرتبة بالطريقة نفسها التي يرتبها بها مدرب التعلم، مع سبب اختيار كل منها. يُوجَّه الزوار غير المسجلين إلى دليل المهارات العام.', array['Which pathway closes my gap?','Which learning pathway closes my gap in AI output verification?']::text[], array['أي مسار تعلم يسد فجوتي؟','أي مسار تعلم يسد فجوتي في التحقق من مخرجات الذكاء الاصطناعي؟']::text[], array['/learn/pathways/:id','/my/pathways','/my/coach']::text[], '[{"label":"SkillsFuture Singapore · Careers and Skills Passport","url":"https://www.myskillsfuture.gov.sg/csp","as_of":"2026-10-10"},{"label":"European Commission · Living repository of AI-literacy practices (EU AI Act Article 4)","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-10"}]'::jsonb, array['SG-CAREER','AI-LIT']::text[], true, null, null, null, 4)
insert into kafaa_digest_nudge_rules (id, topic, kind, name_en, name_ar, rule_en, rule_ar, window_days, link, source_feature, benchmark_ids, since, sort) values
('dnr-decay', 'decay', 'future', 'A fast-changing skill may slip a level', 'مهارة سريعة التغيّر قد ينخفض مستواها', 'A skill in the fast decay class that you hold at level 2 or above, whose newest evidence at that level passes its half-life within 60 days. After that date the skill counts one level lower until new evidence arrives.', 'مهارة من فئة التقادم السريع تحملها بالمستوى 2 أو أعلى، ويتجاوز أحدث دليل عليها بهذا المستوى نصف عمره خلال 60 يوماً. بعد ذلك التاريخ تُحتسب المهارة بمستوى أدنى حتى يصل دليل جديد.', 60, '/my/skills/confidence', 'FS03', array['SG-CAREER','CORP']::text[], '2026-10-12', 1),
('dnr-goal', 'goal', 'future', 'A skill goal is due', 'موعد هدف مهاري يقترب', 'One of your skill goals reaches its target date within 30 days (or passed it in the last 30) while your level is still below the target; a goal without a date asks you to give it one.', 'يصل أحد أهدافك المهارية إلى موعده خلال 30 يوماً (أو تجاوزه خلال آخر 30 يوماً) بينما لا يزال مستواك دون الهدف؛ والهدف الذي لا موعد له يطلب منك تحديد موعد.', 30, '/my/skills/goals', 'FS33', array['SG-CAREER','CORP']::text[], '2026-10-12', 2),
('dnr-ai_literacy', 'ai_literacy', 'future', 'An AI system you use needs a higher AI fluency rung', 'نظام ذكاء اصطناعي تستخدمه يتطلب مستوى أعلى من الطلاقة', 'A published AI system in the AI-literacy register has a user group that covers all staff or your job family and needs an AI fluency rung (or a single skill cell) you have not yet evidenced.', 'لنظام ذكاء اصطناعي منشور في سجل الإلمام بالذكاء الاصطناعي مجموعة مستخدمين تشمل جميع الموظفين أو عائلتك الوظيفية، وتتطلب مستوى من سلّم الطلاقة (أو خلية مهارة) لم تثبته بعد.', null, '/my/ai-fluency', 'FS36', array['SG-CAREER','CORP']::text[], '2026-10-12', 3),
('dnr-role_profile', 'role_profile', 'future', 'Your role''s 2030 profile was published or changed', 'نُشر ملف دورك لعام 2030 أو تغيّر', 'The 2030 profile of your current role was published, or a new version replaced it, in the last 28 days. It is a planning assumption: no deployment decision is implied.', 'نُشر ملف دورك الحالي لعام 2030، أو حلّت محله نسخة جديدة، خلال آخر 28 يوماً. إنه افتراض تخطيطي، دون أي قرار نشر ضمني.', 28, '/my/role-2030', 'FS05', array['SG-CAREER','CORP']::text[], '2026-10-12', 4),
('dnr-rising_skill', 'rising_skill', 'future', 'A skill is rising in your area', 'مهارة صاعدة في مجالك', 'A skill the latest quarterly Skills on the Rise list marks as growing for your job family (or, when the list names no family, one your role''s 2030 profile or one of your goals asks for), that you hold below level 2. Read from the published list only: signals under 10 are suppressed there.', 'مهارة تصنّفها أحدث قائمة فصلية للمهارات الصاعدة بأنها في نمو لعائلتك الوظيفية (أو، إن لم تسمِّ القائمة عائلة، يطلبها ملف دورك لعام 2030 أو أحد أهدافك)، وتحملها بمستوى أقل من 2. تُقرأ من القائمة المنشورة فقط، حيث تُحجب الإشارات التي تقل عن 10.', null, '/skills', 'FS70', array['SG-CAREER','CORP']::text[], '2026-10-12', 5),
('dnr-future_gig', 'future_gig', 'future', 'A new future-skills gig builds one of your skills', 'مهمة جديدة للمهارات المستقبلية تبني إحدى مهاراتك', 'An open future-skills gig posted in the last 21 days, open to your job family, with a seat left, that builds a skill from your goals or your role''s 2030 profile. Not shown when the gig is already in your digest as a match, or when you opted out of marketplace ranking.', 'مهمة مفتوحة للمهارات المستقبلية نُشرت خلال آخر 21 يوماً، متاحة لعائلتك الوظيفية وفيها مقعد شاغر، وتبني مهارة من أهدافك أو من ملف دورك لعام 2030. لا تظهر إذا كانت ضمن ملخصك كفرصة مطابقة، أو إذا اخترت عدم ترتيب السوق.', 21, '/opportunities/future', 'FS27', array['SG-CAREER','CORP']::text[], '2026-10-12', 6),
('dnr-pathway', 'pathway', 'future', 'A new learning pathway fits your next level', 'مسار تعلّم جديد يناسب مستواك التالي', 'A future-skill learning pathway published or updated in the last 28 days that takes one of your future skills exactly one level up (never past the target), which you have not started.', 'مسار تعلّم للمهارات المستقبلية نُشر أو حُدّث خلال آخر 28 يوماً، يرفع إحدى مهاراتك المستقبلية مستوى واحداً بالضبط (ولا يتجاوز الهدف)، ولم تبدأه بعد.', 28, '/learn/pathways', 'FS17', array['SG-CAREER','CORP']::text[], '2026-10-12', 7),
('dnr-fellowship', 'fellowship', 'approval', 'A fellowship milestone waits for your sign-off', 'مرحلة زمالة بانتظار اعتمادك', 'A fellow or their university submitted a fellowship milestone that names you as the supervisor; it waits for your sign-off or a return note.', 'قدّم زميل باحث أو جامعته مرحلة من مراحل الزمالة تسمّيك مشرفاً؛ وهي بانتظار اعتمادك أو ملاحظة إعادة.', null, '/universities/fellowships', 'FS67', array['SG-CAREER','CORP']::text[], '2026-10-12', 8)
insert into kafaa_engine_cards (id, engine_surface, module, route, feature, title_en, title_ar, purpose_en, purpose_ar, owner_en, owner_ar, inputs_used, inputs_excluded, scoring_functions, weight_keys, output_en, output_ar, oversight_en, oversight_ar, limitations_en, limitations_ar, opt_out, version, last_changed_at, last_change_id, sources, sort, kernel_surface, ranks, fairness_metric, fairness_none) values
('skill_suggestions', 'skills', 'M28', '/my/skills/suggestions', 'FS72', 'Skills you may have', 'مهارات قد تمتلكها', 'Suggests up to six skills I may already have, from my work and learning records, so I can confirm, reject or say "not me". Nothing is shown to anyone else until I confirm.', 'يقترح حتى ست مهارات قد أمتلكها بالفعل، من سجلات عملي وتعلّمي، لأؤكدها أو أرفضها أو أقول "لا تخصني". لا يظهر شيء لأي شخص آخر حتى أؤكد.', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', '[{"key":"person_skills","en":"The skills I already hold and how each is evidenced (held skills are never suggested)","ar":"المهارات التي أمتلكها وكيف ثبتت كل منها (لا تُقترح المهارات المثبتة)"},{"key":"opportunity_applications","en":"Gigs and opportunities I completed, and which skills the signed-off outcome levelled","ar":"الفرص والمهام التي أكملتها، والمهارات التي حدّد مستواها الاعتماد النهائي"},{"key":"contributions","en":"My validated expert contributions (lectures and knowledge assets)","ar":"مساهماتي الخبيرة المعتمدة (المحاضرات وأصول المعرفة)"},{"key":"xapi_statements","en":"My learning-record statements in the last year (refresher answers, simulator scenarios, knowledge assets used)","ar":"بيانات سجل تعلّمي خلال العام الماضي (إجابات المراجعات وسيناريوهات المحاكي وأصول المعرفة المستخدمة)"},{"key":"skill_co_occurrence","en":"Which skills staff hold together (counts only, groups under 10 never used, me excluded)","ar":"المهارات التي يمتلكها الموظفون معاً (أعداد فقط، لا تُستخدم المجموعات الأقل من 10، وأنا مستبعد)"},{"key":"skills_adjacency","en":"The catalogue''s list of skills next to each other","ar":"قائمة الكتالوج للمهارات المتجاورة"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m28/suggestions.ts#inferSuggestions','sql:kafaa_ssg_candidates']::text[], '{}'::text[], 'Up to six suggestions, strongest first, each with its reasons; confirming adds my own claim (never more than claimed), rejecting or "not me" hides it for 180 days.', 'حتى ستة اقتراحات، الأقوى أولاً، لكل منها أسبابه؛ التأكيد يضيف ادعائي الخاص (ولا يتجاوز درجة الادعاء)، والرفض أو "لا تخصني" يخفيه 180 يوماً.', 'The rules and points are published on the card and the page; suggestions are private to me and never reach a manager. It never decides anything on its own: I choose, and a claim stays a claim until someone validates it.', 'القواعد والنقاط منشورة على البطاقة والصفحة؛ والاقتراحات خاصة بي ولا تصل إلى أي مدير. لا يقرّر شيئاً بمفرده: أنا من يختار، ويبقى الادعاء ادعاءً حتى يعتمده شخص.', 'It only sees what Kafa''a records; a skill learned elsewhere will not be suggested. Co-occurrence reflects who holds what today, not what a role needs.', 'لا يرى إلا ما تسجّله كفاءة؛ ولن تُقترح مهارة اكتُسبت في مكان آخر. ويعكس الاقتران من يمتلك ماذا اليوم، لا ما يحتاجه الدور.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"LinkedIn Economic Graph research","url":"https://economicgraph.linkedin.com/research","as_of":"2026-10-11"}]'::jsonb, 35, 'rules', 'content', 'suggestion_offered', null)
